// whenUnfocusedLabel is named once: the tests read it.
const whenUnfocusedLabel = "When unfocused"

// imageVerificationLabel is named once: the help texts point at it.
const imageVerificationLabel = "Verify image signatures"

func cycle(label string, ref func(*config.Config) *string, options []string, hint string) field {
	return field{Label: label, Kind: kindCycle, str: ref, Options: options, hint: hint}
}

// cycleWithDefault is a cycle field whose empty value stands for def.
func cycleWithDefault(label string, ref func(*config.Config) *string, options []string, def, hint string) field {
	f := cycle(label, ref, options, hint)
	f.def = def
	return f
}

// withAuto returns the theme list with auto right after default: it is a way of
// choosing, not a theme, so it is not in the list of themes itself.
func withAuto(themes []string) []string {
	out := make([]string, 0, len(themes)+1)
	for i, name := range themes {
		if name == config.ThemeAuto {
			continue
		}
		out = append(out, name)
		if i == 0 {
			out = append(out, config.ThemeAuto)
		}
	}
	return out
}

// themeInUseText is the Theme in use row: the name, and the reason in
// parentheses when there is one. Plain text (Rule 122). A view built before the
// router resolved anything says so rather than showing an empty row.
func themeInUseText(f ThemeFacts) string {
	if f.InUse == "" {
		return "unknown"
	}
	if f.Reason == "" {
		return f.InUse
	}
	return f.InUse + " (" + f.Reason + ")"
}

func static(label, value, hint string) field {
	return field{Label: label, Kind: kindStatic, fact: value, hint: hint}
}

func secret(label, value, hint string) field {
	return field{Label: label, Kind: kindSecret, fact: value, hint: hint}
}

// mcpState is the sentence the State row shows.
//
// The three cases are distinct on purpose: "not enabled" is a choice, "not
// started" is a failure, and an address is neither. Collapsing the first two
// into "off" would make a taken port look like a setting nobody turned on.
func mcpState(mcp MCPFacts) string {
	switch {
	case mcp.Addr != "":
		return "serving on http://" + mcp.Addr
	case mcp.Reason != "":
		return "not started — " + mcp.Reason
	default:
		return "not enabled for this context"
	}
}

// ── reading and writing ─────────────────────────────────────────────────────

// Value renders the setting as the text the field edits.
func (f field) Value(c *config.Config) string {

// GetFooterHeight is the tab bar, a blank line and the info line (Rule 124).
func (m Model) GetFooterHeight() int { return 3 }

// RenderFooter draws the tab bar, then the hint or message line.
func (m Model) RenderFooter(width int) string {
	tabs := make([]theme.TabItem, 0, len(m.sections))
	for _, s := range m.sections {
		tabs = append(tabs, theme.TabItem{Label: s.Title})
	}
	tabBar := theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, m.activeTab), width)

	// The field's hint is the derived status: it is a permanent property of
	// where the cursor is, so it has no timer and any message displaces it.
	info := m.footer.View(width, m.status())

	return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
}

// status is the derived footer line (Rule 128): an app.motion the file holds
// outside its set is a standing fact, so it is a warning-level Status on the
// app tab rather than a message that would expire; otherwise the focused
// field's hint.
func (m Model) status() sharedcomponents.Status {
	if m.activeTab >= 0 && m.activeTab < len(m.sections) && m.sections[m.activeTab].Title == "app" &&
		!m.config.App.MotionValid() {
		return sharedcomponents.Status{
			Text: fmt.Sprintf("%s %q is not %s or %s — rows keep blinking",
				motionLabel, m.config.App.Motion, config.MotionBlink, config.MotionStatic),
			Level: sharedcomponents.LevelWarning,
		}
	}
	return sharedcomponents.Status{Text: m.hint(m.current())}
}

// GetShortcuts lists only what is not self-evident (Rules 130, 137, 138).
// ↑↓ and tab are deliberately absent.
// GetShortcuts lists the three controls a field can take, greying the two the
// focused field does not (Rule 130).
//
// It used to return one of three single-entry lists, so the column changed
// shape on every ↑↓ — in a form, where the cursor moves constantly. `←→` and
// `space` are greyed rather than refused with a message: they are controls, not
// actions, and a footer line on every stray arrow key in a form would be noise.
//
// `↑↓` is never greyed because it always moves; only its wording changes, since
// a cycle or a checkbox has already persisted by the time the cursor leaves.
//
// `esc` is announced although Rule 138 calls the key obvious, because what it
// does here is not: it saves without moving. It is greyed on exactly the fields
// where it would do nothing — the ones that have already written.
func (m Model) GetShortcuts() shortcut.Shortcuts {
	field := m.current()

	move := "Move between fields"
	if field.takesText() {
		move = "Save and move on"
	}

	return []shortcut.Shortcut{
		{Key: "↑↓", Description: move},
					"The tools tab says where each tool runs from, and heads each one with its\n" +
					"state: required and there, required and missing, or not used. The tools\n" +
					"are detected at start, on a context switch, when a source, binary or image\n" +
					"is saved, and on ctrl+r there.",
			},
			{
				Title: "Scan tool source",
				Body: "auto    the binary when there is one, the Docker image otherwise\n" +
					"binary  the configured path, else the name on PATH — fails if absent\n" +
					"image   the Docker image, even when a binary is installed",
			},
			{
				Title: "MCP server",
				Body: "It runs inside dk, over HTTP, and only while dk runs. Enable it here,\n" +
					"then point your agent at http://<listen>/ with the token as a bearer:\n" +
					"space reveals it on the Token row. It is stored in the secret backend,\n" +
					"never in a file — so put it in your agent's own config, not in a\n" +
					"committed .mcp.json, where it would reach the remote on the first push.\n" +
					"\n" +
					"The address is a loopback one and should stay that way: an agent in a\n" +
					"container reaches it at host.docker.internal, and the LAN never can.\n" +
					"Switching context restarts the server, which drops any open session —\n" +
					"that is deliberate, so no agent quietly starts reading another context.\n" +
					"\n" +
					"Y on the mcp tab copies the Claude Code command, address and token\n" +
					"filled in. It is written for the host: from a container, replace the\n" +
					"address with host.docker.internal. The clipboard is readable by any\n" +
					"process in your session, so paste it and move on.",
			},
			{
				Title: "Gauge glyph",
				Body: "shade (default) draws every gauge cell as ░ and tells fill from track by\n" +
					"colour. block fills with a solid █ over a ░ track, which keeps the bar\n" +
					"readable under the cursor. █ is drawn double-width by some terminals\n" +
					"(East Asian ambiguous width); if the gauge columns overflow, go back\n" +
					"to shade. It is not picked from your locale: only you know the terminal.",
			},
			{
				Title: "Motion",
				Body: "blink (default) makes a running row's dot " + indicator.Glyph(indicator.Running, true) + " blink once a\n" +
					"second. static keeps it a steady " + indicator.Glyph(indicator.Running, true) + ", same glyph and color,\n" +
					"with no periodic redraw. It is per context and applies as you cycle it.\n" +
					"A value in the file that is neither keeps blinking, and the footer says so.",
			},
			{
				Title: "When unfocused",
				Body: "pause (default) suspends the animation and the periodic refreshes of\n" +
					"the dashboard, images, containers, Ports and :agent-usage while the\n" +
					"terminal has no focus, and catches up when it comes back. run suspends\n" +
					"nothing. It is per context and applies as you cycle it; it needs a\n" +
					"terminal that reports focus.",
			},
			{
				Title: "Secret backend",
				Body: "Changing it is confirmed, and stored secrets are not migrated:\n" +
					"the " + m.vocab().Name + " token and registry passwords have to be entered again.",
			},
