1	package security
2	
3	import (
4		"fmt"
5		"reflect"
6		"slices"
7		"strings"
8		"testing"
9	
10		tea "charm.land/bubbletea/v2"
11		"github.com/charmbracelet/x/ansi"
12	
13		"github.com/anthnel/devdesk/internal/remediation"
14		"github.com/anthnel/devdesk/internal/scan"
15		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17	)
18	
19	// DEVDESK-686 (S-01), criteria 1 to 6: the Pod Security label on the
20	// Misconfigurations tab, the filter on `p`, its header and the standing warning
21	// of an invalid scan.pss_profile. Footer timers are never run: the footer is
22	// read through Text and Level.
23	
24	const (
25		pssPage       = "https://kubernetes.io/docs/concepts/security/pod-security-standards/"
26		pssBaselineLn = pssPage + "#baseline"
27		pssRestrictLn = pssPage + "#restricted"
28	)
29	
30	// pssFinding is a Kubernetes misconfiguration the way a scan records it.
31	func pssFinding(id, title, file string, sev scan.SeverityLevel) scan.Finding {
32		return scan.Finding{
33			ID: id, Title: title, Severity: sev, Source: scan.SourceTrivyMisconfig,
34			File: file, Line: 4, EndLine: 12, IaCType: "kubernetes",
35		}
36	}
37	
38	// pssFixtures: six Pod Security findings (three baseline, three restricted,
39	// one of them read from Trivy's anchor) and three that are not Pod Security.
40	// The severities are chosen so that the severity filter and the Pod Security
41	// one give different answers.
42	func pssFixtures() []scan.Finding {
43		unconfined := pssFinding("KSV-0104", "Seccomp policies disabled", "a.yaml", scan.SeverityMedium)
44		unconfined.SeccompOrigin = "unconfined"
